fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x0a0a0a);
    host::display::draw_string(8, 8, "SENSOR LEVELS", 0x808080, 1);
    let rh: i32 = (h - 60) / 6;
    let mut i: i32 = 0;
    while i < 6 {
        let v: i32 = (i * 37) % 80 + 15;
        let y: i32 = 40 + i * rh;
        let len: i32 = v * (w - 120) / 100;
        host::display::draw_char(8, y + rh / 2 - 8, 65 + i, 0xffffff, 2);
        host::display::fill_rect(32, y + 6, len, rh - 12, 0x50b070);
        host::display::draw_number(36 + len, y + rh / 2 - 8, v, 0xc0c0c0, 2);
        i = i + 1;
    }
    host::display::present();
}
